import { readFile, stat, writeFile, mkdir } from 'fs/promises';
import { resolve, dirname, join } from 'path';
import chalk from 'chalk';
import { glob } from 'glob';

interface Rule {
  id: string;
  name: string;
  pattern: RegExp;
  severity: 'CRITICAL' | 'WARNING' | 'INFO';
  message: string;
  fix: string;
}

interface Finding {
  rule_id: string;
  rule_name: string;
  severity: string;
  line: number;
  code: string;
  message: string;
  fix: string;
}

const RULES: Rule[] = [
  {
    id: 'A001',
    name: 'missing-alt-text',
    pattern: /<img(?![^>]*alt=)[^>]*>/i,
    severity: 'CRITICAL',
    message: 'Image missing alt attribute — WCAG 1.1.1 violation',
    fix: 'Add alt="" for decorative images or descriptive alt text for informational images',
  },
  {
    id: 'A002',
    name: 'missing-aria-label',
    pattern: /<button(?![^>]*(?:aria-label|aria-labelledby))[^>]*>\s*<(?:svg|img|i|span)/i,
    severity: 'WARNING',
    message: 'Icon-only button without aria-label',
    fix: 'Add aria-label describing the button action',
  },
  {
    id: 'A003',
    name: 'hardcoded-color',
    pattern: /(?:color|background|border):\s*#[0-9a-fA-F]{3,8}/i,
    severity: 'INFO',
    message: 'Hardcoded color value — use design tokens instead',
    fix: 'Replace with CSS custom property: var(--color-primary-500)',
  },
  {
    id: 'A004',
    name: 'px-font-size',
    pattern: /font-size:\s*\d+px/i,
    severity: 'WARNING',
    message: 'Font size in px — use rem for accessibility',
    fix: 'Convert to rem: 16px = 1rem',
  },
  {
    id: 'A005',
    name: 'magic-z-index',
    pattern: /z-index:\s*(?:999|9999|99999)/i,
    severity: 'WARNING',
    message: 'Magic z-index value — use token scale',
    fix: 'Define z-index tokens: --z-dropdown: 100, --z-modal: 200, --z-toast: 300',
  },
  {
    id: 'A006',
    name: 'important-override',
    pattern: /!important/i,
    severity: 'WARNING',
    message: '!important override detected — indicates specificity issues',
    fix: 'Refactor CSS specificity instead of using !important',
  },
  {
    id: 'A007',
    name: 'inline-style',
    pattern: /style=\{?\{[^}]+\}\}?|style="[^"]*"/i,
    severity: 'INFO',
    message: 'Inline style detected — extract to CSS module or styled-component',
    fix: 'Move styles to external stylesheet or CSS-in-JS',
  },
  {
    id: 'A008',
    name: 'missing-focus-visible',
    pattern: /:focus\s*\{[^}]*outline:\s*(?:none|0)/i,
    severity: 'CRITICAL',
    message: 'Focus outline removed — WCAG 2.4.7 violation',
    fix: 'Use :focus-visible instead and provide visible focus indicator',
  },
  {
    id: 'A009',
    name: 'low-tap-target',
    pattern: /(?:width|height|min-width|min-height):\s*(?:[1-3][0-9]|[0-9])px/i,
    severity: 'WARNING',
    message: 'Potential low tap target — minimum 44px recommended',
    fix: 'Ensure interactive elements are at least 44x44px',
  },
  {
    id: 'A010',
    name: 'missing-lang',
    pattern: /<html(?![^>]*lang=)/i,
    severity: 'CRITICAL',
    message: 'HTML element missing lang attribute',
    fix: 'Add lang="en" (or appropriate language) to <html>',
  },
  {
    id: 'A011',
    name: 'autoplaying-media',
    pattern: /<(?:video|audio)(?=[^>]*autoplay)/i,
    severity: 'WARNING',
    message: 'Autoplaying media — may cause accessibility issues',
    fix: 'Add muted attribute or provide pause controls',
  },
  {
    id: 'A012',
    name: 'color-only-indicator',
    pattern: /(?:color|background-color):\s*(?:red|green|#(?:f00|0f0|ff0000|00ff00))/i,
    severity: 'WARNING',
    message: 'Color-only status indicator — add icon or text for colorblind users',
    fix: 'Add supporting icon, text, or pattern to convey meaning',
  },
  // --- AI Hallucination Checks (2026 Deep Research) ---
  {
    id: 'AI001',
    name: 'dynamic-class-interpolation',
    pattern: /className=\{`[^`]*\$\{[^}]*\}[^`]*`\}/,
    severity: 'CRITICAL',
    message: 'Tailwind interpolation detected — JIT compiler cannot extract these classes',
    fix: 'Use a safelist map object: className={colorMap[props.color]}',
  },
  {
    id: 'AI005',
    name: 'non-existent-utility',
    pattern: /text-shadow-(?:sm|md|lg|xl)/,
    severity: 'WARNING',
    message: 'Hallucinated utility "text-shadow" — does not exist in Tailwind defaults',
    fix: 'Use drop-shadow-md or a custom plugin',
  },
  {
    id: 'AI008',
    name: 'pseudo-transparency-contrast',
    pattern: /bg-(?:black|white|slate-\d{3})\/(?:10|20|30|40|50)(?!\d)/,
    severity: 'WARNING',
    message: 'Low contrast pseudo-transparency used on potential text background',
    fix: 'Use glassmorphism: backdrop-filter: blur(4px) brightness(0.5)',
  },
  {
    id: 'AI010',
    name: 'arbitrary-calc-spacing',
    pattern: /w-\[calc\([^]]*?[+\-/*](?![_])[^]]*?\)\]/,
    severity: 'CRITICAL',
    message: 'Tailwind arbitrary value missing underscores in calc()',
    fix: 'Replace spaces with underscores: w-[calc(100%_-_20px)]',
  },
  {
    id: 'AI013',
    name: 'vh-mobile-bug',
    pattern: /(?:h|min-h)-screen/,
    severity: 'WARNING',
    message: 'h-screen causes layout shifts on mobile browsers (address bar resize)',
    fix: 'Use dynamic viewport height: h-[100dvh]',
  },
  {
    id: 'AI015',
    name: 'target-blank-vuln',
    pattern: /target="_blank"(?![^>]*rel=)/,
    severity: 'WARNING',
    message: 'target="_blank" validation missing rel="noopener noreferrer"',
    fix: 'Add rel="noopener noreferrer" to prevent tabnabbing',
  },
];

async function auditFile(filepath: string): Promise<Finding[]> {
  try {
    const stats = await stat(filepath);
    if (stats.isDirectory()) return [];

    const content = await readFile(filepath, 'utf-8');
    const lines = content.split('\n');
    const findings: Finding[] = [];

    for (const rule of RULES) {
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (!line) continue;

        if (rule.pattern.test(line)) {
          findings.push({
            rule_id: rule.id,
            rule_name: rule.name,
            severity: rule.severity,
            line: i + 1,
            code: line.trim().substring(0, 80),
            message: rule.message,
            fix: rule.fix,
          });
        }
      }
    }
    return findings;
  } catch (err) {
    console.warn(chalk.yellow(`Could not read file ${filepath}:`), err);
    return [];
  }
}



// ... (existing imports)

export async function auditCommand(files: string | string[], options: { format?: string; output?: string }) {
  // ... (existing file expansion logic)
  const filePatterns = Array.isArray(files) ? files : [files];
  const expandedFiles: string[] = [];

  for (const pattern of filePatterns) {
    const matches = await glob(pattern);
    if (matches.length > 0) expandedFiles.push(...matches);
    else expandedFiles.push(pattern);
  }

  const allFindings: { file: string; findings: Finding[] }[] = [];
  let totalIssueCount = 0;

  for (const file of expandedFiles) {
    const findings = await auditFile(file);
    if (findings.length > 0) {
      allFindings.push({ file, findings });
      totalIssueCount += findings.length;
    }
  }

  // Determine output path and format
  let outputPath = options.output;
  let format = options.format || 'text';

  if (outputPath) {
    // Enforce 'output/' directory if not present and not an absolute path
    if (!outputPath.startsWith('/') && !outputPath.startsWith('output/')) {
        outputPath = join('output', outputPath);
    }

    if (outputPath.endsWith('.json')) format = 'json';
    if (outputPath.endsWith('.md')) format = 'markdown';
  }

  let outputContent = '';

  if (format === 'json') {
     // ... (JSON generation)
    outputContent = JSON.stringify({ 
      summary: { totalBytes: 0, totalFiles: expandedFiles.length, issues: totalIssueCount },
      details: allFindings 
    }, null, 2);
  } else if (format === 'markdown') {
     // ... (Markdown generation)
    outputContent = `# UI Design System Audit Report\n\n`;
    outputContent += `**Date:** ${new Date().toLocaleString()}\n`;
    outputContent += `**Files Scanned:** ${expandedFiles.length}\n`;
    outputContent += `**Total Issues:** ${totalIssueCount}\n\n`;

    if (totalIssueCount === 0) {
      outputContent += `✅ **No issues found.** Great job!\n`;
    } else {
      for (const { file, findings } of allFindings) {
        const critical = findings.filter(f => f.severity === 'CRITICAL').length;
        const warning = findings.filter(f => f.severity === 'WARNING').length;
        const info = findings.filter(f => f.severity === 'INFO').length;

        outputContent += `## 📄 \`${file}\`\n`;
        outputContent += `Summary: 🔴 ${critical} Critical | 🟡 ${warning} Warnings | 🔵 ${info} Info\n\n`;
        outputContent += `| Line | Severity | Rule | Message | Fix |\n`;
        outputContent += `| :--- | :--- | :--- | :--- | :--- |\n`;

        const sorted = findings.sort((a, b) => {
           if (a.severity === 'CRITICAL' && b.severity !== 'CRITICAL') return -1;
           if (b.severity === 'CRITICAL' && a.severity !== 'CRITICAL') return 1;
           return a.line - b.line;
        });

        for (const f of sorted) {
          const icon = f.severity === 'CRITICAL' ? '🔴' : f.severity === 'WARNING' ? '🟡' : '🔵';
          outputContent += `| ${f.line} | ${icon} ${f.severity} | \`${f.rule_id}\` | ${f.message} <br> _Code:_ \`${f.code.replaceAll('|', '\\|')}\` | ${f.fix} |\n`;
        }
        outputContent += `\n`;
      }
    }
  } else {
    // ... (Text generation)
    if (totalIssueCount === 0) {
      outputContent = chalk.green('\n  No issues found!');
    } else {
      for (const { file, findings } of allFindings) {
        const critical = findings.filter(f => f.severity === 'CRITICAL').length;
        const warning = findings.filter(f => f.severity === 'WARNING').length;
        const info = findings.filter(f => f.severity === 'INFO').length;

        outputContent += `\n  ${chalk.bold('UI AUDIT')}: ${file}\n`;
        outputContent += `  ${chalk.red(critical + ' critical')} | ${chalk.yellow(warning + ' warnings')} | ${chalk.blue(info + ' info')}\n\n`;

        const sorted = findings.sort((a, b) => {
           if (a.severity === 'CRITICAL' && b.severity !== 'CRITICAL') return -1;
           if (b.severity === 'CRITICAL' && a.severity !== 'CRITICAL') return 1;
           return a.line - b.line;
        });

        for (const f of sorted) {
          const icon = f.severity === 'CRITICAL' ? '🔴' : f.severity === 'WARNING' ? '🟡' : '🔵';
          outputContent += `  ${icon} L${f.line} [${f.rule_id}] ${chalk.bold(f.message)}\n`;
          outputContent += `     ${chalk.gray('Code:')} ${f.code}\n`;
          outputContent += `     ${chalk.green('Fix:')}  ${f.fix}\n\n`;
        }
      }
    }
  }

  if (outputPath) {
    const dir = dirname(outputPath);
    if (dir !== '.') {
        await mkdir(dir, { recursive: true });
    }
    await writeFile(outputPath, outputContent);
    console.log(chalk.green(`\nAudit report saved to ${outputPath}`));
  } else {
    console.log(outputContent);
  }
}

import chalk from 'chalk';
import { searchDesign } from '../lib/search';
import { generateAllTokens, generateTypographyScale, hexToHsl, hslToHex } from '../lib/generators';
import { writeFile } from 'fs/promises';

interface GenerateOptions {
  stack?: string;
  output?: string;
  format?: 'json' | 'css' | 'text' | 'markdown';
}

// --- Extraction Logic ---

async function extractPrimaryColor(results: Record<string, any[]>): Promise<string> {
   // Priority 1: Check 'color' domain (colors.csv) for structured hex
   if (results['color']) {
     for (const hit of results['color']) {
       const data = JSON.parse(hit.raw || '{}');
       // Check for explicit hex columns
       for (const key of ['Primary (Hex)', 'Primary Hex', 'Hex', 'Primary']) {
         if (data[key] && String(data[key]).startsWith('#')) {
           return String(data[key]).trim(); // Return immediately if found in colors.csv
         }
       }
     }
   }

   // Priority 2: Check 'style' and 'product' domains with Regex extraction
   const colorRegex = /#([0-9A-Fa-f]{3,6})\b/;
   for (const domain of ['style', 'product', 'landing', 'color']) { // Check color again as fallback
     if (results[domain]) {
       for (const hit of results[domain]) {
         const data = hit.data || {};

         // Look in specific columns first
         const targetKeys = ['Primary Colors', 'Primary (Hex)', 'Primary', 'primary', 'Design System Variables', 'CSS/Technical Keywords', 'Background (Hex)'];

         for (const key of targetKeys) {
            if (data[key]) {
              const match = String(data[key]).match(colorRegex);
              if (match) return match[0];
            }
         }
       }
     }
   }
   return '#2563EB'; // Fallback Blue
}

async function extractFont(results: Record<string, any[]>): Promise<string> {
  // Priority 1: 'typography' domain
  if (results['typography']) {
    for (const hit of results['typography']) {
       const data = hit.data || {};
       // Typography.csv has 'Heading Font' column
       if (data['Heading Font']) return String(data['Heading Font']).trim();
       if (data['Font Pairing Name']) {
          // If name is "Playfair + Source", take the first one
          const fontPairing = String(data['Font Pairing Name']).trim();
          // Ensure fontPairing is not "null" or "undefined" string from String() conversion
          if (fontPairing && fontPairing !== 'null' && fontPairing !== 'undefined') {
            return fontPairing.split('+')[0]?.trim() || 'Inter';
          }
       }
    }
  }

  // Priority 2: Extract from 'style' domain keywords
  if (results['style']) {
     for (const hit of results['style']) {
        const data = hit.data || {};
        const text = (data['CSS/Technical Keywords'] || '') + (data['Design System Variables'] || '');

        // Naive check for common fonts in our dataset
        const commonFonts = ['Inter', 'Roboto', 'Open Sans', 'Lato', 'Montserrat', 'Playfair Display', 'Merriweather', 'Space Grotesk', 'Courier New', 'Share Tech Mono', 'Russo One'];
        for (const font of commonFonts) {
           if (text.toLowerCase().includes(font.toLowerCase())) return font;
        }

        if (text.includes('monospace')) return 'Courier New';
        if (text.includes('serif')) return 'Merriweather';
     }
  }
  return 'Inter';
}

async function extractStyleName(results: Record<string, any[]>): Promise<string> {
    // Try to find a style name from 'style' domain
    if (results['style']) {
        for (const hit of results['style']) {
             const data = hit.data || {};
             if (data['Style Category']) return data['Style Category'];
             if (data['name']) return data['name'];
        }
    }
    // Fallback: Use the query title-cased if reasonable length
    return 'Custom Design';
}

// --- Architectural Palette Generator ---

type ColorScale = Record<number, string>;
interface ArchitecturalPalette {
  primary: ColorScale;
  neutral: ColorScale;
  success: ColorScale;
  warning: ColorScale;
  error: ColorScale;
}

function generateTwScale(baseHex: string, saturationAdjust: number = 0): ColorScale {
  const [h, s, l] = hexToHsl(baseHex);
  const scale: ColorScale = {};

  // Figma/Tailwind standard lightness steps (approximate)
  const steps = [
    { stop: 50, l: 95 },
    { stop: 100, l: 90 },
    { stop: 200, l: 80 },
    { stop: 300, l: 70 },
    { stop: 400, l: 60 },
    { stop: 500, l: 50 }, // Base
    { stop: 600, l: 40 },
    { stop: 700, l: 30 },
    { stop: 800, l: 20 },
    { stop: 900, l: 10 },
    { stop: 950, l: 5 },
  ];

  steps.forEach(step => {
    // Optical adjustment: very light/dark shades often need slightly more saturation to not look washed out
    let newS = s + saturationAdjust;
    if (step.stop <= 100 || step.stop >= 900) newS += 5;

    // Clamp saturation
    newS = Math.max(0, Math.min(100, newS));

    scale[step.stop] = hslToHex(h, newS, step.l);
  });

  return scale;
}

function generateArchitecturalPalette(primaryHex: string): ArchitecturalPalette {
  return {
    primary: generateTwScale(primaryHex),
    // Neutral: Desaturated primary (classic architectural pattern)
    neutral: generateTwScale(primaryHex, -15), // Reduced saturation
    // Semantic Colors (fixed hues, matching primary lightness rhythm)
    success: generateTwScale('#22C55E'), // Green-500
    warning: generateTwScale('#EAB308'), // Yellow-500
    error: generateTwScale('#EF4444'),   // Red-500
  };
}

// --- Markdown Generator ---


function generateEnhancedMarkdown(system: any, components: { atoms: any[], molecules: any[], organisms: any[] }) {
  const { meta, style, palette, type_scale, tokens } = system;
  const stackInfo = meta.stack ? ` | **Tech Stack**: ${meta.stack}` : '';

  const renderSection = (title: string, items: any[]) => {
    if (!items || !items.length) return '';
    return `## ${title}
${items.map((item: any) => `
### ${item.title}
> ${item.data.Description || ''}

| Feature | Details |
| :--- | :--- |
| **Usage** | ${item.data.Usage || 'N/A'} |
| **Variants** | ${item.data.State_Variants || 'N/A'} |
| **CSS Variable** | \`${item.data.CSS_Variables || 'N/A'}\` |

**Code Example (Tailwind)**
\`\`\`tsx
${item.data.Code_Snippet || '// No snippet available'}
\`\`\`

> [!TIP]
> **Best Practice**: ${item.data.Best_Practices || 'Follow standard UI guidelines.'}

> [!NOTE]
> **Accessibility**: ${item.data.Accessibility_Note || 'Ensure accessible contrast and semantic HTML.'}

`).join('\n')}
`;
  };

  let md = `# Design System: ${style.name}\n\n`;
  md += `> **Query**: "${meta.query}"${stackInfo} | **Generated**: ${new Date(meta.generated_at).toLocaleDateString()}\n\n`;

  md += `## 01. Foundation\n`;
  md += `- **Primary Color**: \`${style.primary_color}\` ![${style.primary_color}](https://via.placeholder.com/15/${style.primary_color.substring(1)}/000000?text=+)\n`;
  md += `- **Typography**: **${style.font_family}** (Headings & Body)\n\n`;

  md += `### Color Palette\n`;
  const renderScale = (name: string, scale: Record<number, string>) => {
    let table = `#### ${name}\n`;
    table += `| Stop | Hex | Preview |\n| :--- | :--- | :--- |\n`;
    for (const [stop, hex] of Object.entries(scale)) {
      const cleanHex = hex.substring(1);
      table += `| **${stop}** | \`${hex}\` | ![${hex}](https://via.placeholder.com/80x30/${cleanHex}/${cleanHex}?text=+) |\n`;
    }
    return table + '\n';
  };

  md += renderScale('Primary Brand', palette.primary);
  md += renderScale('Neutral', palette.neutral);

  md += `### Tokens
- **Spacing Base**: ${tokens.spacing?.base || '4px'}
- **Radius**: ${tokens.radius?.default || '4px'}
- **Shadows**: Soft, layered shadows for depth.

`;

  md += `## 02. Atoms
${renderSection('Atoms', components.atoms)}

## 03. Molecules
${renderSection('Molecules', components.molecules)}

## 04. Organisms
${renderSection('Organisms', components.organisms)}

---
*Generated by Design Pro CLI v0.1.1*`;
  return md;
}

// --- Main Command ---

export async function generateSystemCommand(query: string, options: GenerateOptions) {
  // 1. Search across domains
  const domains = ['product', 'style', 'color', 'landing', 'typography', 'reasoning', 'ux', 'chart'];
  const allResults: Record<string, any[]> = {};

  for (const domain of domains) {
    const hits = await searchDesign(query, domain);
    if (hits.length > 0) {
      allResults[domain] = hits;
    }
  }

  // 2. Extract key parameters
  const primaryColor = await extractPrimaryColor(allResults);
  const fontFamily = await extractFont(allResults);
  const styleName = await extractStyleName(allResults);

  // 3. Generate System
  const architecturalPalette = generateArchitecturalPalette(primaryColor);
  const typeScale = generateTypographyScale(16, 1.25, 8);
  const tokens = generateAllTokens(primaryColor, '#64748B', 12, fontFamily);

  const system = {
    meta: {
      query,
      stack: options.stack,
      generated_at: new Date().toISOString(),
      version: '2.0.0',
    },
    style: {
      name: styleName,
      primary_color: primaryColor,
      font_family: fontFamily,
    },
    palette: architecturalPalette,
    type_scale: typeScale,
    tokens,
  };

  // 4. Gather Components
  const atoms = await searchDesign('Atom', 'components');
  const molecules = await searchDesign('Molecule', 'components');
  const organisms = await searchDesign('Organism', 'components');

  // Determine Output Format
  let outputContent = '';
  const isMarkdown = options.output?.endsWith('.md') || options.format === 'markdown';

  if (isMarkdown) {
    outputContent = generateEnhancedMarkdown(system, { atoms, molecules, organisms });
  } else if (options.format === 'json') {
    outputContent = JSON.stringify({ ...system, components: { atoms, molecules, organisms } }, null, 2);
  } else {
    // Legacy CLI Text output
    console.log(chalk.bold(`\n  Design System: ${styleName}`));
    console.log(`  Query: ${query}`);
    console.log(`  Primary: ${chalk.hex(primaryColor)(primaryColor)}`);
    console.log(`  Font: ${fontFamily}`);
    console.log(chalk.green('  (Full architectural palette generated internally)'));
    return;
  }

  // 4. Write Output or Print
  if (options.output) {
    await writeFile(options.output, outputContent);
    console.log(chalk.green(`  ✨ Design system saved to: ${options.output}`));
  } else {
    console.log(outputContent);
  }
}

import { readFile } from 'fs/promises';
import { join } from 'path';
import { parse } from 'csv-parse/sync';
import chalk from 'chalk';

const DATA_FILE = join(import.meta.dir, '../data/icon-libraries.csv');

interface IconLibrary {
  name: string;
  count: string;
  type: string;
  best_for: string;
  docs_url: string;
  cdn_url: string;
  implementation_type: string;
}

export async function iconsCommand(query?: string) {
  try {
    const csvContent = await readFile(DATA_FILE, 'utf-8');
    const records = parse(csvContent, {
      columns: true,
      skip_empty_lines: true,
      trim: true,
    }) as IconLibrary[];

    if (query) {
      const results = records.filter((r) => 
        r.name.toLowerCase().includes(query.toLowerCase())
      );

      if (results.length === 0) {
        console.log(chalk.yellow(`No icon libraries found matching "${query}"`));
        return;
      }

      console.log(`\n# Icon Libraries Matching "${query}"\n`);
      for (const r of results) {
        console.log(`## ${r.name}`);
        console.log(`- **Count**: ${r.count}`);
        console.log(`- **Type**: ${r.implementation_type}`);
        console.log(`- **Best For**: ${r.best_for}`);
        console.log(`- **Docs**: ${r.docs_url}`);
        console.log(`- **CDN**: \`${r.cdn_url}\``);
        console.log('');
      }
    } else {
      console.log(`\n# Top Icon Libraries (2025)\n`);
      console.log('| Name | Count | Type | Best For |');
      console.log('|---|---|---|---|');
      for (const r of records) {
        console.log(`| ${r.name} | ${r.count} | ${r.implementation_type} | ${r.best_for} |`);
      }
      console.log('\nRun `design-cli icons [name]` for details.\n');
    }

  } catch (err) {
