  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: auto;
  gap: 16px;
}

.bento-card-wide {
  grid-column: span 2;
}

.bento-card-tall {
  grid-row: span 2;
}

.bento-card {
  background: #ffffff;
  border-radius: 24px;
  padding: 32px;
  border: 1px solid oklch(0 0 0 / 0.06);
  overflow: hidden;
}
```

